@Service
public class CheckoutService {
    @Autowired private OrderRepository orderRepo;
    @Autowired private KafkaTemplate<String, OrderPaidEvent> kafka;

    @Transactional
    public void completeCheckout(String orderId) {
        Order order = orderRepo.findById(orderId).orElseThrow();
        order.setStatus("PAID");
        orderRepo.save(order);

        // BUG: Dual-write hazard. If network fails or JVM dies right here, Kafka event is lost
        kafka.send("order-paid-topic", new OrderPaidEvent(orderId, order.getAmount()));
    }
}

